// TextEmbeddingSortField is a field FindPage orders TextEmbedding rows by, by its
// schema name (D60, amended): its primary key, or a column of one value of
// text, a number or a time.
type TextEmbeddingSortField string

const (
	TextEmbeddingSortById   TextEmbeddingSortField = "id"
	TextEmbeddingSortByText TextEmbeddingSortField = "text"
)

// TextEmbeddingSort is the order FindPage reads TextEmbedding rows in: Field,
// ascending, or descending when Desc; ties break by id in the same
// direction. The zero value orders by id, ascending.
type TextEmbeddingSort struct {
	Field TextEmbeddingSortField
	Desc  bool
}

// ParseTextEmbeddingSort reads a sort as a page request writes it, "text" or
// "-text": an error for a field TextEmbedding cannot be sorted by.
func ParseTextEmbeddingSort(text string) (TextEmbeddingSort, error) {
	parsed := TextEmbeddingSort{Field: TextEmbeddingSortField(strings.TrimPrefix(text, "-")), Desc: strings.HasPrefix(text, "-")}
	switch parsed.Field {
	case TextEmbeddingSortById, TextEmbeddingSortByText:
		return parsed, nil
	}
	return TextEmbeddingSort{}, fmt.Errorf("orm: TextEmbedding sorts by id and text, not %q", text)
}

// TextEmbeddingUniqueKey names a unique key of TextEmbedding that UpsertOne and
// UpsertMany are keyed by (D79, D89): its primary key, a @unique field, or a
// unique @index, by its fields joined by ",".
type TextEmbeddingUniqueKey string

const (
	TextEmbeddingUniqueById TextEmbeddingUniqueKey = "id"
)

// TextEmbeddingPageKey is the position of a TextEmbedding row in a FindPage order: the
// row's id, as a cursor holds it, {"id": ...}. FindPage reads the row's
// value of its sort field from the table, so a key is the same in every order
// and its length is the id's, whatever the row holds (D60, amended).
type TextEmbeddingPageKey struct {
	Id types.IdentityUUID `json:"id"`
}

// arg is the key's id as the repository writes its column. A key without
// one is ErrPageKey.
func (k *TextEmbeddingPageKey) arg() (any, error) {
	var zeroKey types.IdentityUUID
	if k.Id == zeroKey {
		return nil, fmt.Errorf("%w: the TextEmbedding key holds no id", ErrPageKey)
	}
	return k.Id.ToUUID(), nil
}

// textEmbeddingPageKeyOf is row's key: its id.
func textEmbeddingPageKeyOf(row *types.TextEmbedding) *TextEmbeddingPageKey {
	key := &TextEmbeddingPageKey{}
	if row.Id != nil {
		key.Id = *row.Id
	}
	return key
}

// TextEmbeddingPageOptions are FindPage's options.
type TextEmbeddingPageOptions struct {
	// Fields specifies which fields to select, as FindMany's do; zero is an
	// error. A page reads the id too, which Next holds.
	Fields TextEmbeddingFields
	// Sort is the order the rows are read in.
	Sort TextEmbeddingSort
	// After is the key of the last row of the page before, nil for the first page.
	After *TextEmbeddingPageKey
	// Limit is the rows a page holds: 1 or more, 100 when 0.
	Limit int
	// IncludeDeleted includes soft-deleted records in results (default false)
	IncludeDeleted bool
}

// TextEmbeddingPage is a page of TextEmbedding rows in FindPage's order: at most
// Limit rows, and Next, the key of the last of them, when more rows follow.
type TextEmbeddingPage struct {
	Rows []*types.TextEmbedding
	Next *TextEmbeddingPageKey
}

